import base64, csv, hashlib, io, json, os, re, subprocess, sys, tarfile, time
from pathlib import Path
subprocess.run([sys.executable, '-m', 'pip', 'uninstall', '-y', 'torchao'], check=True)
import torch
if torch.cuda.device_count() < 2: raise RuntimeError('Two distinct CUDA GPUs are required')
gpu_info = subprocess.run(['nvidia-smi', '--query-gpu=index,uuid,name,memory.free,temperature.gpu',
                           '--format=csv,noheader'], capture_output=True, text=True, check=True).stdout
print('GPU_INFO', gpu_info, flush=True)
raw = base64.b64decode('')
if hashlib.sha256(raw).hexdigest() != 'cac28f7c8221f5c1e239f788a8eaa07120f7050e9acce75ee176365433a97bf9': raise RuntimeError('source archive mismatch')
root = Path('/kaggle/temp/fault-src'); root.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as outer:
    for member in outer.getmembers():
        with tarfile.open(fileobj=io.BytesIO(outer.extractfile(member).read()), mode='r:') as inner:
            inner.extractall(root, filter='data')
folder = root / 'experiments/recipes/ticket-sorter-hinglish'
subprocess.run([sys.executable, '-I', str(root / 'experiments/recipes/validate_dataset.py'), str(folder)], check=True)
sys.path[:0] = [str(root / 'packages/ekido_core'), str(root / 'runtime')]
from ekido_runtime import distill, train
def rows(path):
    with path.open(encoding='utf-8', newline='') as f: return list(csv.DictReader(f))
train_rows, test_rows = rows(folder / 'train.csv'), rows(folder / 'test.csv')
out = Path('/kaggle/working/two-t4-fault'); out.mkdir(parents=True, exist_ok=True)
dataset = out / 'dataset.jsonl'
digest, nbytes = train.write_dataset(dataset, train_rows, test_rows)
spec = distill.build_student_spec('ticket-sorter-hinglish', student_model='Qwen/Qwen2.5-1.5B-Instruct',
       student_revision='989aa7980e4cf806f80c7fef2b1adb7bc71aa306', digest=digest, nbytes=nbytes,
       train_rows=len(train_rows), test_rows=len(test_rows), steps=400)
spec['optimizer']['lr'] = 3e-4; spec['checkpoint_every_steps'] = 80
config = {'micro_batch': 2, 'accumulation': 4, 'amp': 'fp16', 'grad_checkpointing': True,
          'attention_impl': 'sdpa', 'loader_workers': 0}
(out/'spec.json').write_text(json.dumps(spec, indent=2), encoding='utf-8')
(out/'exec-config.json').write_text(json.dumps(config, indent=2), encoding='utf-8')
common = [sys.executable, '-u', '-m', 'ekido_runtime.train', '--spec', str(out/'spec.json'),
          '--dataset', str(dataset), '--out', str(out/'train'), '--device', 'cuda',
          '--exec-config', str(out/'exec-config.json')]
def env_for(index):
    env = os.environ.copy()
    env['CUDA_VISIBLE_DEVICES'] = str(index)
    env['PYTHONPATH'] = str(root/'packages/ekido_core') + os.pathsep + str(root/'runtime')
    return env
proc = subprocess.Popen(common, env=env_for(0), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                        text=True, bufsize=1)
killed_step = None
with (out/'before-kill.log').open('w', encoding='utf-8') as log:
    for line in proc.stdout:
        log.write(line); log.flush(); print(line, end='', flush=True)
        match = re.match(r'step (\d+)/400 ', line)
        if match and int(match.group(1)) == 105:
            killed_step = 105; kill_time = time.monotonic(); proc.kill(); break
    proc.wait()
if killed_step != 105: raise RuntimeError('training exited before the planned fault')
checkpoint = out/'train/checkpoints/step-80'
if not (checkpoint/'manifest.json').is_file(): raise RuntimeError('step-80 checkpoint missing')
resumed_step = None; first_step_seconds = None
proc = subprocess.Popen(common + ['--resume', str(checkpoint)], env=env_for(1),
                        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
with (out/'after-resume.log').open('w', encoding='utf-8') as log:
    for line in proc.stdout:
        log.write(line); log.flush(); print(line, end='', flush=True)
        match = re.match(r'resumed at logical step (\d+)', line)
        if match: resumed_step = int(match.group(1))
        if first_step_seconds is None and re.match(r'step 81/400 ', line):
            first_step_seconds = round(time.monotonic()-kill_time, 3)
    rc = proc.wait()
if rc or resumed_step != 80 or first_step_seconds is None:
    raise RuntimeError('second GPU did not resume successfully')
evidence = json.loads((out/'train/evidence.json').read_text(encoding='utf-8'))
summary = {'core_revision': '0a9db037170024a1f32748e0b5dcbe14a1a88a3a', 'worker_revision': '74bf4e753ab30f4ce3b88a577a16b425c6fac923',
           'gpu_info': gpu_info, 'first_gpu_index': 0, 'resume_gpu_index': 1,
           'killed_after_step': killed_step, 'resumed_step': resumed_step,
           'lost_steps': killed_step-resumed_step, 'seconds_until_first_resumed_step': first_step_seconds,
           'completed_step': evidence['completed_step'], 'test_pass_rate': evidence['eval']['pass_rate'],
           'test_examples': evidence['eval']['examples'],
           'test_note': 'Previously reused synthetic test; not an independent evaluation',
           'staging_note': 'Local two-GPU process fault; not an end-to-end staging settlement'}
(out/'fault-summary.json').write_text(json.dumps(summary, indent=2), encoding='utf-8')
print('FAULT_RESULT', json.dumps(summary), flush=True)
